<script setup lang="ts">import { computed, onMounted } from 'vue'; import { CalendarDays, Clock3 } from 'lucide-vue-next'; import PageHeader from '../components/PageHeader.vue'; import EmptyState from '../components/EmptyState.vue'; import { useTasksStore } from '../stores/tasks'; import { formatDate, formatTime } from '../composables/useFormat'; const store = useTasksStore(); onMounted(() => store.load('status=pending&limit=200')); const byDay = computed(() => { const map = new Map<string, typeof store.items>(); store.items.filter(t => t.deadline).forEach(t => { const key = formatDate(t.deadline); map.set(key, [...(map.get(key) || []), t]) }); return [...map.entries()] });</script>
<template><section class="page-content"><PageHeader eyebrow="时间线" title="日历" description="按截止时间看一周内需要推进的事情。"><div class="calendar-view-switch"><button class="active">周</button><button>月</button></div></PageHeader><section class="calendar-hero panel"><div class="calendar-heading"><CalendarDays :size="21" /><div><strong>本周安排</strong><span>截止时间按本地时区显示</span></div></div><div class="calendar-days"><div v-for="day in ['一','二','三','四','五','六','日']" :key="day" class="calendar-day"><span>{{ day }}</span><strong>{{ 17 + ['一','二','三','四','五','六','日'].indexOf(day) }}</strong><i :class="{ 'has-task': day === '四' || day === '五' }"></i></div></div></section><div v-if="byDay.length" class="calendar-list"><section v-for="[day, tasks] in byDay" :key="day" class="calendar-group"><h3>{{ day }}</h3><article v-for="task in tasks" :key="task.id" class="calendar-task"><span class="calendar-rule"></span><div><strong>{{ task.title }}</strong><p>{{ task.course || task.category }}</p></div><span class="calendar-time"><Clock3 :size="14" />{{ formatTime(task.deadline) }}</span></article></section></div><section v-else class="panel"><EmptyState title="还没有排期" description="给任务加上截止时间，它就会出现在这条时间线上。" /></section></section></template>
